/* nepui — Carousel */

.np-carousel,
[data-np-carousel] {
  --np-carousel-gap: 1rem;
  --np-carousel-item-basis: 100%;
  --np-carousel-height: auto;
  --np-carousel-button-size: 2rem;
  --np-carousel-button-offset: 3rem;
  --np-carousel-dot-size: 0.5rem;
  --np-carousel-dot-gap: 0.5rem;
  --np-carousel-dots-offset: 1rem;

  position: relative;
  box-sizing: border-box;
  min-width: 0;
}

.np-carousel-viewport,
[data-np-carousel-viewport] {
  box-sizing: border-box;
  overflow-x: auto;
  overflow-y: hidden;
  overscroll-behavior-x: contain;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  outline: none;
}

:is(.np-carousel-viewport, [data-np-carousel-viewport])::-webkit-scrollbar {
  display: none;
}

:is(.np-carousel-viewport, [data-np-carousel-viewport]):focus-visible {
  border-radius: 0.25rem;
  box-shadow: 0 0 0 3px color-mix(in oklch, var(--np-ring), transparent 50%);
}

:is(.np-carousel-vertical, [data-orientation="vertical"]):is(
    .np-carousel,
    [data-np-carousel]
  )
  :is(.np-carousel-viewport, [data-np-carousel-viewport]) {
  height: var(--np-carousel-height);
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior-x: auto;
  overscroll-behavior-y: contain;
  scroll-snap-type: y mandatory;
}

:is(.np-carousel-viewport, [data-np-carousel-viewport]):is(
  .np-carousel-embla,
  [data-embla]
) {
  overflow: hidden;
  scroll-snap-type: none;
}

.np-carousel-content,
[data-np-carousel-content] {
  box-sizing: border-box;
  display: flex;
  margin-inline-start: calc(var(--np-carousel-gap) * -1);
}

:is(.np-carousel-vertical, [data-orientation="vertical"]):is(
    .np-carousel,
    [data-np-carousel]
  )
  :is(.np-carousel-content, [data-np-carousel-content]) {
  flex-direction: column;
  height: calc(100% + var(--np-carousel-gap));
  margin-inline-start: 0;
  margin-block-start: calc(var(--np-carousel-gap) * -1);
}

.np-carousel-item,
[data-np-carousel-item] {
  box-sizing: border-box;
  flex: 0 0 var(--np-carousel-item-basis);
  min-width: 0;
  min-height: 0;
  padding-inline-start: var(--np-carousel-gap);
  /* The slide box starts one gap before its content; snap on the content. */
  scroll-margin-inline-start: calc(var(--np-carousel-gap) * -1);
  scroll-snap-align: start;
}

:is(.np-carousel-vertical, [data-orientation="vertical"]):is(
    .np-carousel,
    [data-np-carousel]
  )
  :is(.np-carousel-item, [data-np-carousel-item]) {
  padding-inline-start: 0;
  padding-block-start: var(--np-carousel-gap);
  scroll-margin-inline-start: 0;
  scroll-margin-block-start: calc(var(--np-carousel-gap) * -1);
}

/* Put the nepui Button classes on the same element:
   <button class="np-button np-button-outline np-button-icon-sm np-carousel-previous"> */
:is(.np-carousel, [data-np-carousel])
  :is(
    .np-carousel-previous,
    [data-np-carousel-previous],
    .np-carousel-next,
    [data-np-carousel-next]
  ) {
  position: absolute;
  z-index: 1;
  box-sizing: border-box;
  width: var(--np-carousel-button-size);
  height: var(--np-carousel-button-size);
  margin: auto;
  padding: 0;
  border-radius: 9999px;
  /* Centred on the other axis, without `translate`, so RTL needs nothing. */
  inset-block: 0;
}

:is(.np-carousel, [data-np-carousel])
  :is(.np-carousel-previous, [data-np-carousel-previous]) {
  inset-inline-start: calc(var(--np-carousel-button-offset) * -1);
  inset-inline-end: auto;
}

:is(.np-carousel, [data-np-carousel])
  :is(.np-carousel-next, [data-np-carousel-next]) {
  inset-inline-end: calc(var(--np-carousel-button-offset) * -1);
  inset-inline-start: auto;
}

:is(.np-carousel, [data-np-carousel])
  :is(
    .np-carousel-previous,
    [data-np-carousel-previous],
    .np-carousel-next,
    [data-np-carousel-next]
  ):dir(rtl) {
  rotate: 180deg;
}

/* Vertical: above and below, centred across. */
:is(.np-carousel-vertical, [data-orientation="vertical"]):is(
    .np-carousel,
    [data-np-carousel]
  )
  :is(
    .np-carousel-previous,
    [data-np-carousel-previous],
    .np-carousel-next,
    [data-np-carousel-next]
  ) {
  inset-block: auto;
  inset-inline: 0;
  rotate: 90deg;
}

:is(.np-carousel-vertical, [data-orientation="vertical"]):is(
    .np-carousel,
    [data-np-carousel]
  )
  :is(.np-carousel-previous, [data-np-carousel-previous]) {
  inset-block-start: calc(var(--np-carousel-button-offset) * -1);
}

:is(.np-carousel-vertical, [data-orientation="vertical"]):is(
    .np-carousel,
    [data-np-carousel]
  )
  :is(.np-carousel-next, [data-np-carousel-next]) {
  inset-block-end: calc(var(--np-carousel-button-offset) * -1);
}

:is(.np-carousel, [data-np-carousel])
  :is(.np-carousel-dots, [data-np-carousel-dots]) {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: var(--np-carousel-dot-gap);
  margin-block-start: var(--np-carousel-dots-offset);
}

:is(.np-carousel, [data-np-carousel])
  :is(.np-carousel-dot, [data-np-carousel-dot]) {
  box-sizing: border-box;
  flex: none;
  width: var(--np-carousel-dot-size);
  height: var(--np-carousel-dot-size);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 9999px;
  background: var(--np-border);
  cursor: pointer;
  transition:
    background-color 150ms,
    width 150ms;
}

:is(.np-carousel, [data-np-carousel])
  :is(.np-carousel-dot, [data-np-carousel-dot]):hover {
  background: var(--np-muted-foreground);
}

:is(.np-carousel, [data-np-carousel])
  :is(.np-carousel-dot, [data-np-carousel-dot]):is(
    [aria-current="true"],
    [data-active]
  ) {
  width: calc(var(--np-carousel-dot-size) * 2.5);
  background: var(--np-primary);
}

:is(.np-carousel, [data-np-carousel])
  :is(.np-carousel-dot, [data-np-carousel-dot]):focus-visible {
  outline: 2px solid var(--np-ring);
  outline-offset: 2px;
}

:is(.np-carousel-vertical, [data-orientation="vertical"]):is(
    .np-carousel,
    [data-np-carousel]
  )
  :is(.np-carousel-dots, [data-np-carousel-dots]) {
  position: absolute;
  inset-block: 0;
  inset-inline-end: calc(
    var(--np-carousel-dots-offset) * -1 - var(--np-carousel-dot-size)
  );
  flex-direction: column;
  flex-wrap: nowrap;
  margin: 0;
}

:is(.np-carousel-vertical, [data-orientation="vertical"]):is(
    .np-carousel,
    [data-np-carousel]
  )
  :is(.np-carousel-dot, [data-np-carousel-dot]):is(
    [aria-current="true"],
    [data-active]
  ) {
  width: var(--np-carousel-dot-size);
  height: calc(var(--np-carousel-dot-size) * 2.5);
}

@media (prefers-reduced-motion: reduce) {
  :is(.np-carousel, [data-np-carousel])
    :is(.np-carousel-dot, [data-np-carousel-dot]) {
    transition: none;
  }
}

:is(.np-carousel, [data-np-carousel]):has(
    > :is(.np-carousel-dots, [data-np-carousel-dots])
  ):not(:is(.np-carousel-vertical, [data-orientation="vertical"]))
  > :is(
    .np-carousel-previous,
    [data-np-carousel-previous],
    .np-carousel-next,
    [data-np-carousel-next]
  ) {
  inset-block-end: calc(
    var(--np-carousel-dots-offset) + var(--np-carousel-dot-size)
  );
}

;(function () {
  var ROOT = ".np-carousel, [data-np-carousel]"

  function init(root) {
    if (root.__npCarousel) return
    var viewport = root.querySelector(
      ":scope > .np-carousel-viewport, :scope > [data-np-carousel-viewport]"
    )
    if (!viewport) return
    root.__npCarousel = true

    var prev = root.querySelector(
      ":scope > .np-carousel-previous, :scope > [data-np-carousel-previous]"
    )
    var next = root.querySelector(
      ":scope > .np-carousel-next, :scope > [data-np-carousel-next]"
    )
    var dots = root.querySelector(
      ":scope > .np-carousel-dots, :scope > [data-np-carousel-dots]"
    )
    var vertical = root.matches(
      '.np-carousel-vertical, [data-orientation="vertical"]'
    )

    function items() {
      return Array.prototype.slice.call(
        viewport.querySelectorAll(".np-carousel-item, [data-np-carousel-item]")
      )
    }
    function rtl() {
      return !vertical && getComputedStyle(viewport).direction === "rtl"
    }
    function pos() {
      return Math.abs(vertical ? viewport.scrollTop : viewport.scrollLeft)
    }
    function max() {
      return vertical
        ? viewport.scrollHeight - viewport.clientHeight
        : viewport.scrollWidth - viewport.clientWidth
    }
    function size() {
      return vertical ? viewport.clientHeight : viewport.clientWidth
    }
    function step() {
      var list = items()
      if (list.length < 2) return size() || 1
      var a = list[0].getBoundingClientRect()
      var b = list[1].getBoundingClientRect()
      return Math.abs(vertical ? b.top - a.top : b.left - a.left) || 1
    }
    function count() {
      return Math.max(1, items().length - Math.round(size() / step()) + 1)
    }
    function index() {
      return Math.min(count() - 1, Math.round(pos() / step()))
    }
    function setDisabled(button, disabled) {
      if (!button) return
      if ("disabled" in button) button.disabled = disabled
      else if (disabled) button.setAttribute("aria-disabled", "true")
      else button.removeAttribute("aria-disabled")
    }

    var dotCount = -1
    function renderDots(n, i) {
      if (!dots) return
      if (n !== dotCount) {
        dotCount = n
        dots.textContent = ""
        for (var k = 0; k < n; k++) {
          var b = document.createElement("button")
          b.type = "button"
          b.className = "np-carousel-dot"
          b.setAttribute("aria-label", "Go to slide " + (k + 1))
          b.setAttribute("data-index", String(k))
          dots.appendChild(b)
        }
      }
      for (var m = 0; m < dots.children.length; m++) {
        if (m === i) dots.children[m].setAttribute("aria-current", "true")
        else dots.children[m].removeAttribute("aria-current")
      }
    }

    var last = -1
    var frame = 0
    function update() {
      frame = 0
      var p = pos()
      setDisabled(prev, p <= 1)
      setDisabled(next, p >= max() - 1)
      var i = index()
      renderDots(count(), i)
      if (i !== last) {
        last = i
        root.dispatchEvent(
          new CustomEvent("np-carousel-change", {
            bubbles: true,
            detail: { index: i, count: count() },
          })
        )
      }
    }
    function schedule() {
      if (!frame) frame = requestAnimationFrame(update)
    }

    var target = null
    var timer = 0
    function settle() {
      target = null
    }
    function go(delta) {
      var base = target !== null ? target : index()
      goTo(base + delta)
    }
    function goTo(to) {
      target = Math.max(0, Math.min(count() - 1, to))
      clearTimeout(timer)
      timer = setTimeout(settle, 700)
      var behavior = matchMedia("(prefers-reduced-motion: reduce)").matches
        ? "auto"
        : "smooth"
      var offset = target * step()
      var value = vertical ? offset : rtl() ? -offset : offset
      viewport.scrollTo(
        vertical
          ? { top: value, behavior: behavior }
          : { left: value, behavior: behavior }
      )
    }

    if (dots) {
      dots.addEventListener("click", function (event) {
        var d = event.target.closest && event.target.closest("[data-index]")
        if (d && dots.contains(d)) goTo(Number(d.getAttribute("data-index")))
      })
    }
    var drag = null
    var moved = false
    var dragIndex = 0
    viewport.setAttribute("data-draggable", "")
    function endDrag() {
      viewport.removeAttribute("data-dragging")
    }
    viewport.addEventListener("pointerdown", function (event) {
      if (event.pointerType !== "mouse" || event.button !== 0) return
      if (
        event.target.closest &&
        event.target.closest("input, textarea, select, [contenteditable]")
      )
        return
      drag = {
        x: event.clientX,
        y: event.clientY,
        left: viewport.scrollLeft,
        top: viewport.scrollTop,
      }
      moved = false
      dragIndex = target !== null ? target : index()
    })
    viewport.addEventListener("pointermove", function (event) {
      if (!drag) return
      var dx = event.clientX - drag.x
      var dy = event.clientY - drag.y
      var d = vertical ? dy : dx
      if (!moved) {
        if (Math.abs(d) < 4) return
        moved = true
        clearTimeout(timer)
        target = null
        viewport.setAttribute("data-dragging", "")
        viewport.setPointerCapture(event.pointerId)
      }
      if (vertical) viewport.scrollTop = drag.top - dy
      else viewport.scrollLeft = drag.left - dx
    })
    function release(event) {
      if (!drag) return
      var d = vertical ? event.clientY - drag.y : event.clientX - drag.x
      drag = null
      if (!moved) return
      if (viewport.hasPointerCapture(event.pointerId))
        viewport.releasePointerCapture(event.pointerId)
      var forward = vertical ? d < 0 : rtl() ? d > 0 : d < 0
      var threshold = step() * 0.15
      var to = index()
      if (Math.abs(d) > threshold) to = dragIndex + (forward ? 1 : -1)
      endDrag()
      goTo(to)
    }
    viewport.addEventListener("pointerup", release)
    viewport.addEventListener("pointercancel", release)
    viewport.addEventListener(
      "click",
      function (event) {
        if (moved) {
          event.preventDefault()
          event.stopPropagation()
          moved = false
        }
      },
      true
    )
    viewport.addEventListener("dragstart", function (event) {
      event.preventDefault()
    })

    if (prev)
      prev.addEventListener("click", function () {
        go(-1)
      })
    if (next)
      next.addEventListener("click", function () {
        go(1)
      })

    root.addEventListener("keydown", function (event) {
      if (
        event.defaultPrevented ||
        event.altKey ||
        event.ctrlKey ||
        event.metaKey
      )
        return
      var t = event.target
      if (
        t &&
        (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))
      )
        return
      var back = vertical ? "ArrowUp" : rtl() ? "ArrowRight" : "ArrowLeft"
      var forward = vertical ? "ArrowDown" : rtl() ? "ArrowLeft" : "ArrowRight"
      if (event.key === back) {
        event.preventDefault()
        go(-1)
      } else if (event.key === forward) {
        event.preventDefault()
        go(1)
      }
    })

    viewport.addEventListener("scroll", schedule, { passive: true })
    viewport.addEventListener("scrollend", settle)
    if (typeof ResizeObserver !== "undefined")
      new ResizeObserver(schedule).observe(viewport)
    update()
  }

  function initAll() {
    document.querySelectorAll(ROOT).forEach(init)
  }

  window.NepuiCarousel = { init: init, initAll: initAll }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initAll)
  } else {
    initAll()
  }
})()
